const usdPattern=/^\d+\.\d{2}$/;
function validPrice(value:unknown,location:string):string{
 if(typeof value!=='string'||!usdPattern.test(value)||!Number.isFinite(Number(value)))throw Error('Invalid decimal price from '+location+'. Reload the application.');
 return value;
}
function normalizeProduct(p:Product):Product{return {...p,price:validPrice(p?.price,'product '+String(p?.id))}}
function normalizeProducts(products:Product[]):Product[]{if(!Array.isArray(products))throw Error('Invalid catalog response');return products.map(normalizeProduct)}
function normalizeCart(value:Cart):Cart {
 if(!value||!Array.isArray(value.items))throw Error('Invalid cart response');
 return {...value,total:validPrice(value.total,'cart total'),items:value.items.map(i=>({...i,price:validPrice(i.price,'cart item')}))};
}
function normalizeOrder(value:Order):Order{return {...value,total:validPrice(value?.total,'order')}}
function normalizeOrderDetail(value:OrderDetail):OrderDetail {
 return {...value,total:validPrice(value?.total,'order detail'),items:value.items.map(i=>({...i,price:validPrice(i.price,'order line')}))};
}
function normalizeSupplier(value:SyncItem):SyncItem{return {...value,price:validPrice(value?.price,'supplier product')}}

